                  color="#ffffff"
                  size={40}
                  underlayColor="transparent"
                  containerStyle={{ width: 40, margin: 5 }}
                />
                <Icon
                  type="material-icons"
                  name="equalizer"
                  color="#ffffff"
                  size={40}
                  underlayColor="transparent"
                  containerStyle={{ width: 40, margin: 5 }}
                />
                <Text
                  style={{
                    color: "#ffffff",
                    marginLeft: -5,
                    fontSize: 15,
                  }}
                >
                  {
                    //mostrarViews(item.id)
                    obtenTotalViews(item.id)
                  }
                </Text>
                {!obtenTotalViews(item.id) ? (
                  <Text
                    style={{
                      color: "#ffffff",
                      marginLeft: -5,
                      fontSize: 15,
                    }}
