                item.id == likeUpdatePodcast[98] ||
                item.id == likeUpdatePodcast[99] ||
                item.id == likeUpdatePodcast[100] ? (
                  <Icon
                    type="fontisto"
                    name="like"
                    color="#9a4dff"
                    size={30}
                    underlayColor="transparent"
                    containerStyle={{
                      width: 40,
                      margin: 5,
                      marginTop: 9,
                    }}
                    onPress={() => removePodcastLike(item.id)}
                  />
                ) : (
                  <Icon
                    type="fontisto"
                    name="like"
                    color="#ffffff"
                    size={30}
                    underlayColor="transparent"
                    containerStyle={{
                      width: 40,
                      margin: 5,
