                    }}
                    onPress={() => addPodcastLike(item.id)}
                  />
                )}
                <Text
                  style={{
                    color: "#ffffff",
                    marginLeft: -2,
                    fontSize: 15,
                  }}
                >
                  {
                    //mostrarViews(item.id)
                    obtenTotalFavoritos(item.id)
                  }
                </Text>
                {!obtenTotalFavoritos(item.id) ? (
                  <Text
                    style={{
