        />
      </View>
      <FlatList
        data={listaPodcast}
        keyExtractor={({ id }, index) => id}
        // evita el error de los cambios de columnas
        //  ItemSeparatorComponent={ItemSeparatorView}
        renderItem={ItemView}
        contentContainerStyle={{ paddingBottom: 150 }}
      />
      <View style={styles.menu}>
        <TouchableOpacity
          style={{ flexDirection: "column" }}
