        >
          <Icon
            type="material-community"
            name="leaf"
            color="#ffffff"
            size={35}
            underlayColor="transparent"
            containerStyle={{ width: 50, margin: 5 }}
          />
          <Text style={styles.titleMenu}>Inicio</Text>
        </TouchableOpacity>
        <TouchableOpacity
          style={{ flexDirection: "column" }}
          onPress={() => navigation.navigate("search")}
        >
          <Icon
            type="material-community"
            name="magnify"
            color="#ffffff"
            size={35}
            underlayColor="transparent"
            containerStyle={{ width: 50, margin: 5 }}
