        <TouchableOpacity
          style={{ flexDirection: "column" }}
          onPress={() => navigation.navigate("account")}
        >
          <Icon
            type="material-community"
            name="account-circle"
            color="#ffffff"
            size={35}
            underlayColor="transparent"
            containerStyle={{ width: 50, margin: 5 }}
          />
          <Text style={styles.titleMenu}>Mi AgriFM</Text>
        </TouchableOpacity>
      </View>
    </View>
